head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P8.xml";
scwin.dtsFz530;
scwin.dtsFz531;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.CopyDataSet(opener.dts_Fz530, dts_Fz530);
    $c.stf.setObjectValue(txb_COND_NM, opener.dts_Fz530.getCellData(1, "COND_NM"));
    $c.stf.setObjectValue(txa_COND_CON, opener.dts_Fz530.getCellData(1, "COND_CON"));

    // [신규저장] 이면 저장버튼만 활성화하고 [수정저장]이면 다른이름으로저장, 수정 버튼 활성화
    if ($c.stf.getObjectValue(opener.txb_conditionTitle) == "신규저장") {
        // 신규저장
        $c.stf.showObj(img_btn_other_save, false);
        $c.stf.showObj(img_btn_modify, false);
    } else {
        $c.stf.showObj(img_Confirm, false);
        img_btn_other_save.style.left = 263 + 54;
        img_btn_modify.style.left = 362 + 54;
    }
};




/**
 *  유효성 체크
 */
scwin.fn_ChkValid = function() {
    if ($c.stf.getObjectValue(txb_COND_NM) == "") {
        $c.win.alert("제목을 입력하세요.");
        txb_COND_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_COND_CON) == "") {
        $c.win.alert("상세내용을 입력하세요.");
        txa_COND_CON.Focus();
        return false;
    }
    return true;
};


/**
 * 신규 저장
 */
scwin.fn_Save = function() {
    // 저장될 데이터를 세팅.
    scwin.fn_SetSaveData();
    if (!$c.cp.isModified(dts_Fz530)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }

    // 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    if ($c.stf.getObjectValue(opener.txb_conditionTitle) == "신규저장") {
        // 신규저장

        trs_save.Action = "/ConditionSrchAction.do?method=updateCondition" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&vNewSave=Y";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Fz530)";
        //trs_save.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    } else {
        // 조건읽기를 했을경우

        trs_save.Action = "/ConditionSrchAction.do?method=updateCondition" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&vTmpSave=" + opener.vTmpSave;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Fz530)";
        //trs_save.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};





/**
 * 다른 이름으로 저장
 */
scwin.fn_DuplicateSave = function() {
    // 저장될 데이터를 세팅.
    scwin.fn_SetSaveData();
    if (!$c.cp.isModified(dts_Fz530)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }

    // 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return false;
    }
    if (!confirm("다른 이름으로 저장하시겠습니까?")) {
        return false;
    }
    trs_save.Action = "/ConditionSrchAction.do?method=duplicateCondition" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&vTmpSave=" + opener.vTmpSave;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_Fz530)";
    //trs_save.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};


/**
 * 저장될 데이터를 세팅한다.
 */
scwin.fn_SetSaveData = function() {
    dts_Fz530.setCellData(1, "COND_NM", $c.stf.getObjectValue(txb_COND_NM)); //제목 : 저장팝업에서 세팅
    dts_Fz530.setCellData(1, "COND_CON", $c.stf.getObjectValue(txa_COND_CON)); //상세내용 : 저장팝업에서 세팅

};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    await $c.frame.CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_save_OnSuccess = async function() {
    opener.fn_Reset();
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    await $c.frame.CloseFrame();
};
scwin.trs_save_OnFail = function() {
    $c.win.alert(trs_save.ErrorMsg);
};
scwin.img_btn_other_save_onclick = function() {
    scwin.fn_DuplicateSave();
};
scwin.img_btn_modify_onclick = function() {
    scwin.fn_Save();
};
